(function(){"use strict";var CAP=13500;var BUNDLES={};var root=document.getElementById("qb");if(!root)return;var sumEl=document.getElementById("qb-lines");var totEl=document.getElementById("qb-totals");var boxes=root.querySelectorAll("input[type=checkbox]");var qtys=root.querySelectorAll("input[type=number]");var payBtn=document.getElementById("qb-pay");var payNote=document.getElementById("qb-paynote");var payBtn2=document.getElementById("qb-pay2");function setLabel(b,text){if(!b)return;var spans=b.querySelectorAll(".btn__t");if(!spans.length){b.textContent=text;return}for(var i=0;i<spans.length;i++)spans[i].textContent=text}var PAY_NOTE="Card payment covers the one-off items, + 10% GST, through Stripe. Monthly items start by contract, with the same published numbers.";var closeTot=document.getElementById("qb-close-totals");var payEnabled=false;var payable=[];var oneOffNow=0;var monthlyNow=0;var cappedNow=false;function fmt(n){return"$"+n.toLocaleString("en-AU")}var STORE_KEY="semora.quotation.v1";function keyOf(el){if(el.dataset.bx){var lab=el.closest("label");var amt=lab&&lab.querySelector("input[data-cmo]");return amt&&amt.dataset.label?"b:"+amt.dataset.label:""}if(!el.dataset.label)return"";return(el.type==="number"?"n:":"c:")+el.dataset.label}function saveState(){var state={c:{},n:{}};boxes.forEach(function(el){var k=keyOf(el);if(k&&el.checked)state.c[k]=1});qtys.forEach(function(el){var k=keyOf(el);var v=parseInt(el.value,10);if(k&&v>0)state.n[k]=v});try{window.sessionStorage.setItem(STORE_KEY,JSON.stringify(state))}catch(e){}}function restoreState(){var raw;try{raw=window.sessionStorage.getItem(STORE_KEY)}catch(e){return}if(!raw)return;var state;try{state=JSON.parse(raw)}catch(e){return}if(!state||typeof state!=="object")return;var c=state.c&&typeof state.c==="object"?state.c:{};var n=state.n&&typeof state.n==="object"?state.n:{};var has=function(o,k){return Object.prototype.hasOwnProperty.call(o,k)};qtys.forEach(function(el){var k=keyOf(el);if(!k||!has(n,k))return;var v=parseInt(n[k],10);if(!(v>0))return;var mx=parseInt(el.max,10)||99;el.value=String(Math.min(v,mx))});boxes.forEach(function(el){var k=keyOf(el);if(!k)return;if(el.dataset.bx){var lab=el.closest("label");var amt=lab&&lab.querySelector("input[data-cmo]");el.checked=!!(amt&&(parseInt(amt.value,10)||0)>0);return}el.checked=has(c,k)})}function payVisibility(){var live=payEnabled;var ready=live&&oneOffNow>0;var gst=oneOffNow?Math.round(oneOffNow*.1):0;var inc=oneOffNow+gst;[payBtn,payBtn2].forEach(function(b){if(!b)return;b.hidden=!live;b.disabled=!ready;setLabel(b,ready?"Pay Now — "+fmt(inc):"Select an item to pay")});if(payNote){payNote.hidden=!ready;payNote.textContent=PAY_NOTE}if(closeTot){closeTot.innerHTML=oneOffNow?'<div class="qb-total"><span>Subtotal (ex GST)</span><b>'+fmt(oneOffNow)+'</b></div><div class="qb-total"><span>GST (10%)</span><b>'+fmt(gst)+'</b></div><div class="qb-total qb-total--pay"><span>Total payable (inc GST)</span><b>'+fmt(inc)+"</b></div>":'<p class="qb-close__empty">Tick an item above and the total appears here.</p>'}}function build(){saveState();var lines=[];var oneOff=0,moMenu=0,moBudget=0;payable=[];var bundled={};Object.keys(BUNDLES).forEach(function(g){var all=root.querySelectorAll('input[data-g="'+g+'"]');var on=root.querySelectorAll('input[data-g="'+g+'"]:checked');if(all.length===BUNDLES[g].n&&on.length===BUNDLES[g].n)bundled[g]=true});Object.keys(bundled).forEach(function(g){var b=BUNDLES[g];lines.push([b.label,fmt(b.price),b.note]);oneOff+=b.price});boxes.forEach(function(el){if(el.dataset.bx)return;if(!el.checked)return;if(el.dataset.g&&bundled[el.dataset.g])return;var p=parseInt(el.dataset.p,10)||0;if(el.dataset.mo){if(el.dataset.free){lines.push([el.dataset.label,"Free","included with the monthly engine"])}else{lines.push([el.dataset.label,fmt(p)+" / mo","monthly · 6-month minimum"]);moMenu+=p}}else{var note=el.dataset.t?"delivery "+el.dataset.t:"";if(el.dataset.note)note+=" · "+el.dataset.note;lines.push([el.dataset.label,fmt(p),note]);oneOff+=p;payable.push({label:el.dataset.label})}});Object.keys(bundled).forEach(function(g){root.querySelectorAll('input[data-g="'+g+'"]').forEach(function(el){payable.push({label:el.dataset.label})})});qtys.forEach(function(el){var n=Math.max(0,parseInt(el.value,10)||0);var mx=parseInt(el.max,10)||99;if(n>mx){n=mx;el.value=mx}if(!n)return;if(el.dataset.cmo){var bx=el.closest("label").querySelector("input[data-bx]");if(bx&&!bx.checked)return;lines.push([el.dataset.label,fmt(n)+" / mo","client budget · monthly"]);moBudget+=n;return}var p=(parseInt(el.dataset.p,10)||0)*n;lines.push([el.dataset.label+" × "+n,fmt(p),el.dataset.t?"delivery "+el.dataset.t:""]);oneOff+=p;payable.push({label:el.dataset.label,qty:n})});var capped=moMenu>CAP;var monthly=(capped?CAP:moMenu)+moBudget;if(!lines.length){sumEl.innerHTML='<p class="qb-empty">Build up what you need — each item is priced and timed. We quote the package for you.</p>';totEl.innerHTML="";oneOffNow=0;monthlyNow=0;payVisibility();return}sumEl.innerHTML=lines.map(function(l){return'<div class="qb-line"><div><span>'+l[0]+"</span><em>"+l[2]+"</em></div><b>"+l[1]+"</b></div>"}).join("");var t="";if(oneOff){var gstNow=Math.round(oneOff*.1);t+='<div class="qb-total"><span>Subtotal (ex GST)</span><b>'+fmt(oneOff)+"</b></div>";t+='<div class="qb-total"><span>GST (10%)</span><b>'+fmt(gstNow)+"</b></div>";t+='<div class="qb-total qb-total--pay"><span>Total payable (inc GST)</span><b>'+fmt(oneOff+gstNow)+"</b></div>"}if(monthly){t+='<div class="qb-total"><span>Monthly</span><b>'+(capped?"<s>"+fmt(moMenu+moBudget)+"</s> ":"")+fmt(monthly)+" / mo</b></div>";if(capped){t+='<p class="qb-cap">Managed Growth Pod / Held cap applied — the fixed monthly menu never costs more than '+fmt(CAP)+" a month; client-set budgets ride on top.</p>"}}t+='<p class="qb-fine">GST applies on purchase.</p>';totEl.innerHTML=t;oneOffNow=oneOff;monthlyNow=monthly;cappedNow=capped;payVisibility()}function quoteText(){var out="SEMORA STUDIO — quote request "+new Date().toLocaleDateString("en-AU")+"\n\n";sumEl.querySelectorAll(".qb-line").forEach(function(l){out+=l.querySelector("span").textContent+" — "+l.querySelector("b").textContent+" ("+l.querySelector("em").textContent+")\n"});if(oneOffNow){var gstMail=Math.round(oneOffNow*.1);out+="Subtotal (ex GST): "+fmt(oneOffNow)+"\n";out+="GST (10%): "+fmt(gstMail)+"\n";out+="Total payable (inc GST): "+fmt(oneOffNow+gstMail)+"\n"}if(monthlyNow){out+="Monthly: "+fmt(monthlyNow)+" / mo"+(cappedNow?" (fixed menu capped at "+fmt(CAP)+")":"")+"\n"}out+="GST applies on purchase.\n";return out}boxes.forEach(function(b){b.addEventListener("change",function(){if(b.dataset.bx&&b.checked){var inp=b.closest("label").querySelector("input[data-cmo]");if(inp&&!inp.value)inp.focus()}build()})});qtys.forEach(function(q2){q2.addEventListener("input",function(){if(q2.dataset.cmo){var bx=q2.closest("label").querySelector("input[data-bx]");if(bx)bx.checked=(parseInt(q2.value,10)||0)>0}build()})});var SRC_PATH=(function(){var here=(window.location.pathname||"").replace(/\.html$/,"");return/^\/[a-z0-9-]+$/.test(here)?here:"/quotation"})();var mail=document.getElementById("qb-mail");var mail2=document.getElementById("qb-mail2");[mail,mail2].forEach(function(m){if(m)m.addEventListener("click",function(){m.href="mailto:team@semora.com.au?subject="+encodeURIComponent("Quote request — via semora.com.au"+SRC_PATH)+"&body="+encodeURIComponent(quoteText()+"\nMy details:\nName:\nPractice:\nPhone:\n")})});function fillSheet(){var d=document.getElementById("qsheet-date");var r=document.getElementById("qsheet-ref");var now=new Date;if(d)d.textContent=now.toLocaleDateString("en-AU",{day:"numeric",month:"long",year:"numeric"});var ymd=now.getFullYear()*1e4+(now.getMonth()+1)*100+now.getDate();if(r)r.textContent="Q"+ymd+"-"+String(now.getTime()%1e3).padStart(3,"0");var tt=document.getElementById("qsheet-totals");if(tt){var gst=Math.round(oneOffNow*.1);var rows="";if(oneOffNow){rows+='<div class="qsheet-trow"><span>Subtotal (one-off, ex GST)</span><b>'+fmt(oneOffNow)+"</b></div>";rows+='<div class="qsheet-trow"><span>GST (10%)</span><b>'+fmt(gst)+"</b></div>";rows+='<div class="qsheet-trow qsheet-trow--total"><span>Total payable</span><b>'+fmt(oneOffNow+gst)+"</b></div>"}if(monthlyNow){rows+='<div class="qsheet-trow qsheet-trow--mo"><span>Monthly menu (ex GST, starts by contract'+(cappedNow?", fixed menu capped at "+fmt(CAP):"")+")</span><b>"+fmt(monthlyNow)+" / mo</b></div>"}tt.innerHTML=rows}}window.addEventListener("beforeprint",fillSheet);var pr=document.getElementById("qb-print");if(pr)pr.addEventListener("click",function(){fillSheet();window.print()});if(payBtn||payBtn2){let startCheckout=function(btn){if(!payable.length)return;[payBtn,payBtn2].forEach(function(b){if(b)b.disabled=true});setLabel(btn,"Opening secure payment…");function failed(msg){payVisibility();if(payNote){payNote.hidden=false;payNote.textContent=msg}}fetch("/api/checkout",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({lines:payable})}).then(function(r){return r.json()}).then(function(out){if(out&&out.url){window.location.href=out.url;return}failed(out&&out.error||"Payment could not start. Email the quote instead — same numbers.")}).catch(function(){failed("Payment could not start. Email the quote instead — same numbers.")})};fetch("/api/checkout",{method:"GET"}).then(function(r){return r.json()}).then(function(cfg){payEnabled=!!(cfg&&cfg.enabled);payVisibility()}).catch(function(){payEnabled=false});[payBtn,payBtn2].forEach(function(b){if(b)b.addEventListener("click",function(){startCheckout(b)})})}restoreState();build();var status=document.getElementById("qb-paystatus");if(status){var q=new URLSearchParams(window.location.search);var pv=q.get("payment");var sid=q.get("session_id")||"";if(pv==="success"&&sid){status.hidden=false;status.className="qb-paystatus";status.textContent="Checking the payment…";fetch("/api/checkout?session_id="+encodeURIComponent(sid)).then(function(r){return r.json()}).then(function(v){if(v&&v.paid){status.className="qb-paystatus qb-paystatus--ok";status.textContent="Payment received. We will email you to start delivery."}else{status.textContent="We could not confirm a payment for this visit. If you believe you paid, email team@semora.com.au with your Stripe receipt and we will confirm it."}}).catch(function(){status.textContent="We could not confirm a payment for this visit. If you believe you paid, email team@semora.com.au with your Stripe receipt and we will confirm it."})}else if(pv==="cancelled"){status.hidden=false;status.className="qb-paystatus";status.textContent="Payment was cancelled. "+(oneOffNow||monthlyNow?"Your selection is still here.":"Your selection was not carried back — build it again below and the numbers are the same.")}}})();
